/**
 * Classic home dishes from around the world, for the globe. Each is a simplified home version, and each says so.
 * Same rules as recipes.ts: honest evidence labels, verified https sources, no diet-culture language. Dishes are
 * "classic", never "the most popular": nobody can verify that claim.
 */
export interface Cuisine {
  id: string;
  name: string;
  /** ISO 3166-1 numeric code of the country, for the globe. */
  iso: number;
  region: string;
  blurb: string;
  tradition: string;
  evidence: Strength;
  sources: Source[];
  recipes: WorldRecipe[];
}
export type WorldRecipe = Recipe & { note: string; cuisine: string };
type RawCuisine = Omit<Cuisine, "recipes"> & { recipes: Array<Omit<WorldRecipe, "cuisine">> };

